1	package com.example.starter.runway;
2	
3	import com.example.starter.runway.dto.*;
4	import org.springframework.dao.DuplicateKeyException;
5	import org.springframework.stereotype.Service;
6	import org.springframework.transaction.annotation.Transactional;
7	
8	import java.nio.charset.StandardCharsets;
9	import java.security.MessageDigest;
10	import java.security.NoSuchAlgorithmException;
11	import java.time.Clock;
12	import java.time.Instant;
13	import java.time.temporal.ChronoUnit;
14	import java.util.ArrayList;
15	import java.util.Comparator;
16	import java.util.List;
17	import java.util.Locale;
18	
19	/**
20	 * 跑道临时关闭巡检与开放决策服务：状态流转、幂等、并发与事务边界在此实现。
21	 */
22	@Service
23	public class RunwayService {
24	
25	    private static final String SCOPE_REPORT = "report";
26	    private static final String SCOPE_ASSESSMENT = "assessment";
27	    private static final String SCOPE_REOPEN = "reopen";
28	
29	    private final RunwayEventRepository eventRepository;
30	    private final InspectionRepository inspectionRepository;
31	    private final AssessmentRepository assessmentRepository;
32	    private final NotamRepository notamRepository;
33	    private final WeatherRepository weatherRepository;
34	    private final RoutinePlanRepository routinePlanRepository;
35	    private final RunwayLockRepository runwayLockRepository;
36	    private final RunwayProperties properties;
37	    private final IdempotencyExecutor idempotencyExecutor;
38	    private final Clock clock;
39	
40	    public RunwayService(RunwayEventRepository eventRepository,
41	                         InspectionRepository inspectionRepository,
42	                         AssessmentRepository assessmentRepository,
43	                         NotamRepository notamRepository,
44	                         WeatherRepository weatherRepository,
45	                         RoutinePlanRepository routinePlanRepository,
46	                         RunwayLockRepository runwayLockRepository,
47	                         RunwayProperties properties,
48	                         IdempotencyExecutor idempotencyExecutor,
49	                         Clock clock) {
50	        this.eventRepository = eventRepository;
51	        this.inspectionRepository = inspectionRepository;
52	        this.assessmentRepository = assessmentRepository;
53	        this.notamRepository = notamRepository;
54	        this.weatherRepository = weatherRepository;
55	        this.routinePlanRepository = routinePlanRepository;
56	        this.runwayLockRepository = runwayLockRepository;
57	        this.properties = properties;
58	        this.idempotencyExecutor = idempotencyExecutor;
59	        this.clock = clock;
60	    }
61	
62	    /**
63	     * 接报：即触发临时关闭并同步发布关闭通告；requestId 幂等；同一跑道唯一进行中事件。
64	     */
65	    public ReportResponse report(ReportRequest request) {
66	        String fingerprint = fingerprint(SCOPE_REPORT, request.requestId(), request.runwayId(),
67	                request.eventType().name(), request.reportedAt().toString());
68	        try {
69	            return idempotencyExecutor.execute(SCOPE_REPORT, request.requestId(), fingerprint,
70	                    () -> doReport(request), ReportResponse.class);
71	        } catch (DuplicateKeyException e) {
72	            ReportResponse replayed = idempotencyExecutor.tryReplay(SCOPE_REPORT, request.requestId(),
73	                    fingerprint, ReportResponse.class);
74	            if (replayed != null) {
75	                return replayed;
76	            }
77	            if (isActiveEventConflict(e)) {
78	                throw ApiException.conflict("RUNWAY_ACTIVE_EVENT_EXISTS", "同一跑道已存在进行中的关闭事件");
79	            }
80	            throw e;
81	        }
82	    }
83	
84	    private ReportResponse doReport(ReportRequest request) {
85	        // 与例行“开始”在同一跑道上串行化，得到唯一占用状态；跨跑道持不同锁行互不阻塞。
86	        runwayLockRepository.lockRunway(request.runwayId());
87	        Instant now = clock.instant();
88	        Instant closedAt = request.reportedAt();
89	        Instant deadline = closedAt.plus(properties.inspectionStartLimitMinutes(), ChronoUnit.MINUTES);
90	        RunwayEvent event = new RunwayEvent(0L, request.runwayId(), request.eventType(), EventStatus.CLOSED,
91	                request.reportedAt(), closedAt, deadline, false, null, request.requestId(), now, now);
92	        event = eventRepository.insert(event, 1);
93	        String notamNo = "NTM-C-" + event.id();
94	        notamRepository.insert(new NotamRecord(0L, event.id(), event.runwayId(), NotamAction.CLOSE,
95	                notamNo, closedAt));
96	        preemptRoutinePlans(event, closedAt, now);
97	        return new ReportResponse(event.id(), event.runwayId(), event.status().name(), closedAt, deadline, notamNo);
98	    }
99	
100	    /**
101	     * 紧急关闭抢占：同一事务内取消该跑道“尚未开始”例行计划，已开始计划转中止并保留已完成检查项。
102	     * 被抢占计划置终态并释放获准位（紧急事件结束后可另建新计划，不复活被抢占项）。
103	     */
104	    private void preemptRoutinePlans(RunwayEvent event, Instant closedAt, Instant now) {
105	        List<RoutinePlan> activePlans = routinePlanRepository.findActiveByRunway(event.runwayId());
106	        for (RoutinePlan plan : activePlans) {
107	            RoutinePlanStatus target = switch (plan.status()) {
108	                case STARTED -> RoutinePlanStatus.ABORTED;
109	                case APPROVED, NEEDS_REVIEW -> RoutinePlanStatus.CANCELLED;
110	                default -> null;
111	            };
112	            if (target == null) {
113	                continue;
114	            }
115	            RoutinePlan preempted = new RoutinePlan(plan.id(), plan.runwayId(), plan.windowStart(),
116	                    plan.windowEnd(), plan.durationMinutes(), plan.calendarVersion(), plan.version() + 1,
117	                    target, plan.evidence(), plan.slotFlag(), event.id(), plan.startedAt(), plan.completedAt(),
118	                    closedAt, plan.requestId(), plan.createdAt(), now);
119	            routinePlanRepository.update(preempted);
120	        }
121	    }
122	
123	    /**
124	     * 巡检开始：恰满15分钟未开始判定迟延并升级；低能见度须双人，单人记录不生效；
125	     * 归档后迟到巡检仅登记迟到事件。
126	     */
127	    @Transactional
128	    public InspectionResponse startInspection(long eventId, InspectionRequest request) {
129	        RunwayEvent event = mustFind(eventId);
130	        Instant now = clock.instant();
131	        if (event.status() == EventStatus.ARCHIVED) {
132	            InspectionRecord lateRecord = inspectionRepository.insert(new InspectionRecord(0L, eventId,
133	                    request.startedAt(), request.inspectorCount(), true, true, now));
134	            return new InspectionResponse(lateRecord.id(), eventId, true, event.escalated(), true,
135	                    event.status().name());
136	        }
137	        if (event.status() == EventStatus.REOPENED) {
138	            throw ApiException.conflict("EVENT_NOT_ACTIVE", "事件已恢复开放，不再受理巡检");
139	        }
140	        boolean late = !request.startedAt().isBefore(event.inspectionDeadline());
141	        boolean lowVisibility = weatherRepository.findLatestAtOrBefore(event.runwayId(), request.startedAt())
142	                .map(reading -> reading.rvrMeters() < properties.lowVisibilityRvrThreshold())
143	                .orElse(false);
144	        if (lowVisibility && request.inspectorCount() < 2) {
145	            throw ApiException.unprocessable("LOW_VISIBILITY_REQUIRES_DUAL",
146	                    "低能见度期间巡检须双人执行，单人记录不生效");
147	        }
148	        InspectionRecord record = inspectionRepository.insert(new InspectionRecord(0L, eventId,
149	                request.startedAt(), request.inspectorCount(), late, false, now));
150	        boolean escalated = event.escalated() || late;
151	        EventStatus newStatus = event.status() == EventStatus.CLOSED ? EventStatus.INSPECTING : event.status();
152	        eventRepository.updateStatus(eventId, newStatus, escalated, event.assessmentType(), false, now);
153	        return new InspectionResponse(record.id(), eventId, late, escalated, false, newStatus.name());
154	    }
