275	        }
276	        boolean escalatedMarked = false;
277	        for (InspectionRecord inspection : inspectionRepository.findByEventId(eventId)) {
278	            if (inspection.recordedAfterArchive()) {
279	                timeline.add(new TimelineEntry("LATE_INSPECTION_RECORDED", inspection.startedAt(),
280	                        "归档后迟到巡检记录，仅登记"));
281	                continue;
282	            }
283	            timeline.add(new TimelineEntry("INSPECTION_STARTED", inspection.startedAt(),
284	                    "巡检开始，人数" + inspection.inspectorCount() + (inspection.late() ? "，迟延" : "")));
285	            if (inspection.late() && !escalatedMarked) {
286	                timeline.add(new TimelineEntry("ESCALATED", inspection.startedAt(), "巡检迟延，事件升级"));
287	                escalatedMarked = true;
288	            }
289	        }
290	        for (AssessmentRecord assessment : assessmentRepository.findByEventIdOrderByAssessedAt(eventId)) {
291	            timeline.add(new TimelineEntry("ASSESSED", assessment.assessedAt(),
292	                    "摩擦系数" + assessment.frictionCoefficient().toPlainString()
293	                            + (assessment.passed() ? "，合格" : "，不合格持续关闭")
294	                            + (assessment.retest() ? "（复测）" : "")));
295	        }
296	        if (event.status() == EventStatus.REOPENED) {
297	            notamRepository.findByEventId(eventId).stream()
298	                    .filter(n -> n.action() == NotamAction.REOPEN)
299	                    .findFirst()
300	                    .ifPresent(n -> timeline.add(new TimelineEntry("REOPENED", n.publishedAt(), "恢复开放")));
301	        }
302	        if (event.status() == EventStatus.ARCHIVED) {
303	            timeline.add(new TimelineEntry("ARCHIVED", event.updatedAt(), "事件归档（终态）"));
304	        }
305	        timeline.sort(Comparator.comparing(TimelineEntry::at));
306	        return new EventDetailResponse(event.id(), event.runwayId(), event.eventType().name(),
307	                event.status().name(), event.reportedAt(), event.closedAt(), event.inspectionDeadline(),
308	                event.escalated(), timeline);
309	    }
