359	    private void requireActive(RunwayEvent event, String operation) {
360	        if (event.status() == EventStatus.ARCHIVED) {
361	            throw ApiException.conflict("EVENT_ARCHIVED", "事件已归档，不再受理" + operation);
362	        }
363	        if (event.status() == EventStatus.REOPENED) {
