373	    private String fingerprint(String... parts) {
374	        try {
375	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
376	            byte[] hash = digest.digest(String.join("|", parts).getBytes(StandardCharsets.UTF_8));
377	            StringBuilder hex = new StringBuilder(hash.length * 2);
378	            for (byte b : hash) {
379	                hex.append(Character.forDigit((b >> 4) & 0xF, 16)).append(Character.forDigit(b & 0xF, 16));
380	            }
381	            return hex.toString();
382	        } catch (NoSuchAlgorithmException e) {
383	            throw new IllegalStateException("SHA-256 不可用", e);
384	        }
385	    }
