1	package com.example.starter.runway;
2	
3	import com.example.starter.runway.dto.*;
4	import com.fasterxml.jackson.core.JsonProcessingException;
5	import com.fasterxml.jackson.databind.ObjectMapper;
6	import org.springframework.dao.DuplicateKeyException;
7	import org.springframework.stereotype.Service;
8	import org.springframework.transaction.annotation.Transactional;
9	
10	import java.time.Clock;
11	import java.time.Instant;
12	import java.time.temporal.ChronoUnit;
13	import java.util.ArrayList;
14	import java.util.List;
15	import java.util.Locale;
16	
17	/**
18	 * 例行跑道巡检计划服务：航班日历版本、计划发布/开始/检查回报/完成回报、日历影响查询。
19	 *
20	 * <p>并发与一致性要点：</p>
21	 * <ul>
22	 *   <li>例行开始与紧急接报在同一跑道上先取 runway_lock 行锁串行化，得到唯一占用状态；跨跑道持不同行互不阻塞。</li>
23	 *   <li>同跑道同窗唯一获准由 routine_plan 唯一索引（slot_flag）保证。</li>
24	 *   <li>计划聚合带乐观锁 version（从1开始，成功变更加1），写操作携带 expectedVersion，不符返回409。</li>
25	 *   <li>日历版本仅追加；发布在事务内锁定最大版本行分配版本号，并发发布得到连续唯一新版本。</li>
26	 * </ul>
27	 */
28	@Service
29	public class RoutineService {
30	
31	    static final String SCOPE_CALENDAR = "calendar-publish";
32	    static final String SCOPE_PLAN = "plan-publish";
33	    static final String SCOPE_START = "plan-start";
34	    static final String SCOPE_CHECK = "plan-check";
35	    static final String SCOPE_COMPLETION = "plan-completion";
36	
37	    private final FlightCalendarRepository calendarRepository;
38	    private final FlightOccupancyRepository occupancyRepository;
39	    private final RoutinePlanRepository planRepository;
40	    private final RoutineCheckItemRepository checkItemRepository;
41	    private final RoutineCompletionRepository completionRepository;
42	    private final RunwayEventRepository eventRepository;
43	    private final RunwayLockRepository runwayLockRepository;
44	    private final IdempotencyExecutor idempotencyExecutor;
45	    private final ObjectMapper objectMapper;
46	    private final Clock clock;
47	
48	    public RoutineService(FlightCalendarRepository calendarRepository,
49	                          FlightOccupancyRepository occupancyRepository,
50	                          RoutinePlanRepository planRepository,
51	                          RoutineCheckItemRepository checkItemRepository,
52	                          RoutineCompletionRepository completionRepository,
53	                          RunwayEventRepository eventRepository,
54	                          RunwayLockRepository runwayLockRepository,
55	                          IdempotencyExecutor idempotencyExecutor,
56	                          ObjectMapper objectMapper,
57	                          Clock clock) {
58	        this.calendarRepository = calendarRepository;
59	        this.occupancyRepository = occupancyRepository;
60	        this.planRepository = planRepository;
61	        this.checkItemRepository = checkItemRepository;
62	        this.completionRepository = completionRepository;
63	        this.eventRepository = eventRepository;
64	        this.runwayLockRepository = runwayLockRepository;
65	        this.idempotencyExecutor = idempotencyExecutor;
66	        this.objectMapper = objectMapper;
67	        this.clock = clock;
68	    }
69	
70	    // ============================= 航班日历 =============================
71	
72	    /**
73	     * 发布新航班日历版本：仅追加，版本+1；并发发布以 expectedVersion 乐观判定，仅一个成功。
74	     * 发布后所有“尚未开始（APPROVED）”计划置待重审，已开始计划不自动平移。requestId 幂等。
75	     */
76	    public CalendarPublishResponse publishCalendar(CalendarPublishRequest request) {
77	        for (FlightWindowInput window : request.occupancies()) {
78	            if (!window.windowEnd().isAfter(window.windowStart())) {
79	                throw ApiException.badRequest("INVALID_OCCUPANCY_WINDOW",
80	                        "航班占用窗结束时刻必须晚于开始时刻: " + window.runwayId());
81	            }
82	        }
83	        List<List<String>> windowFields = request.occupancies().stream()
84	                .map(w -> List.of(w.runwayId(), w.windowStart().toString(), w.windowEnd().toString()))
85	                .toList();
86	        String fingerprint = StructuredFingerprint.sha256WithCollection(SCOPE_CALENDAR,
87	                List.of(request.requestId(), String.valueOf(request.expectedVersion()),
88	                        request.publishedAt().toString()),
89	                windowFields);
90	        try {
91	            return idempotencyExecutor.execute(SCOPE_CALENDAR, request.requestId(), fingerprint,
92	                    () -> doPublishCalendar(request), CalendarPublishResponse.class);
93	        } catch (DuplicateKeyException e) {
94	            CalendarPublishResponse replayed = idempotencyExecutor.tryReplay(SCOPE_CALENDAR,
95	                    request.requestId(), fingerprint, CalendarPublishResponse.class);
96	            if (replayed != null) {
97	                return replayed;
98	            }
99	            if (isVersionConflict(e)) {
100	                throw ApiException.conflict("CALENDAR_VERSION_CONFLICT",
101	                        "日历版本已被并发发布推进，请基于最新版本重试");
102	            }
103	            throw e;
104	        }
105	    }
106	
107	    private CalendarPublishResponse doPublishCalendar(CalendarPublishRequest request) {
108	        Instant now = clock.instant();
109	        Integer current = calendarRepository.findMaxVersionForUpdate()
110	                .orElseThrow(() -> ApiException.badRequest("CALENDAR_NOT_INITIALIZED", "航班日历尚未初始化"));
111	        if (current != request.expectedVersion()) {
112	            throw ApiException.conflict("CALENDAR_VERSION_CONFLICT",
113	                    "日历版本已变更，当前最新版本=" + current + "，请求 expectedVersion=" + request.expectedVersion());
114	        }
115	        int newVersion = current + 1;
116	        calendarRepository.insert(newVersion, request.publishedAt(), request.requestId(), now);
117	        List<FlightOccupancyWindow> windows = request.occupancies().stream()
118	                .map(w -> new FlightOccupancyWindow(0L, newVersion, w.runwayId(), w.windowStart(), w.windowEnd()))
119	                .toList();
120	        occupancyRepository.insertBatch(newVersion, windows);
121	
122	        // 仅影响尚未开始的获准计划；快照其ID用于响应，再统一定为待重审。已开始计划不动。
123	        List<Long> approvedIds = planRepository.findApprovedIds();
124	        if (!approvedIds.isEmpty()) {
125	            planRepository.markApprovedStaleForReview(now);
126	        }
127	        return new CalendarPublishResponse(newVersion, request.publishedAt(), approvedIds);
128	    }
129	
130	    // ============================= 例行计划发布 =============================
131	
132	    /**
133	     * 计划申请发布：校验落窗与冻结日历版本下的占用冲突，冻结冲突证据。
134	     * 正长度相交拒绝（422，附证据），端点相接合法；同跑道同窗仅一个获准。requestId 幂等。
135	     */
136	    public PlanResponse publishPlan(PlanPublishRequest request) {
137	        if (!request.windowEnd().isAfter(request.windowStart())) {
138	            throw ApiException.badRequest("INVALID_PLAN_WINDOW", "巡检窗口结束时刻必须晚于开始时刻");
139	        }
140	        Instant inspectionEnd = request.windowStart().plus(request.durationMinutes(), ChronoUnit.MINUTES);
141	        if (inspectionEnd.isAfter(request.windowEnd())) {
142	            throw ApiException.unprocessable("INSPECTION_NOT_WITHIN_WINDOW",
143	                    "巡检时长须完整落在窗口内：巡检结束 " + inspectionEnd + " 晚于窗口结束 " + request.windowEnd());
144	        }
145	        int latest = latestCalendarVersion();
146	        if (request.calendarVersion() != latest) {
147	            throw ApiException.unprocessable("CALENDAR_VERSION_STALE",
148	                    "发布须依据最新航班日历版本，最新=" + latest + "，提交=" + request.calendarVersion());
149	        }
150	        String fingerprint = StructuredFingerprint.sha256(SCOPE_PLAN,
151	                request.requestId(), request.runwayId(), request.windowStart().toString(),
152	                request.windowEnd().toString(), String.valueOf(request.durationMinutes()),
153	                String.valueOf(request.calendarVersion()));
154	        try {
155	            return idempotencyExecutor.execute(SCOPE_PLAN, request.requestId(), fingerprint,
156	                    () -> doPublishPlan(request, inspectionEnd), PlanResponse.class);
157	        } catch (DuplicateKeyException e) {
158	            PlanResponse replayed = idempotencyExecutor.tryReplay(SCOPE_PLAN, request.requestId(),
159	                    fingerprint, PlanResponse.class);
160	            if (replayed != null) {
161	                return replayed;
162	            }
163	            if (isSlotConflict(e)) {
164	                throw ApiException.unprocessable("PLAN_SLOT_OCCUPIED",
165	                        "同跑道同窗已存在一个获准（未终态）例行计划");
166	            }
167	            throw e;
168	        }
169	    }
170	
171	    private PlanResponse doPublishPlan(PlanPublishRequest request, Instant inspectionEnd) {
172	        List<FlightOccupancyWindow> windows =
173	                occupancyRepository.findByVersionAndRunway(request.calendarVersion(), request.runwayId());
174	        ConflictEvidence evidence = buildEvidence(request.runwayId(), request.calendarVersion(),
175	                request.windowStart(), request.windowEnd(), request.windowStart(), inspectionEnd, windows);
176	        if (evidence.conflict()) {
177	            throw ApiException.unprocessable("OCCUPANCY_CONFLICT",
178	                    "巡检区间与合成航班占用窗正长度相交，拒绝发布", writeEvidence(evidence));
179	        }
180	        Instant now = clock.instant();
181	        RoutinePlan plan = new RoutinePlan(0L, request.runwayId(), request.windowStart(), request.windowEnd(),
182	                request.durationMinutes(), request.calendarVersion(), 1, RoutinePlanStatus.APPROVED,
183	                writeEvidence(evidence), 1, null, null, null, null, request.requestId(), now, now);
184	        RoutinePlan saved;
185	        try {
186	            saved = planRepository.insert(plan);
187	        } catch (DuplicateKeyException e) {
188	            if (isSlotConflict(e)) {
189	                throw ApiException.unprocessable("PLAN_SLOT_OCCUPIED",
190	                        "同跑道同窗已存在一个获准（未终态）例行计划");
191	            }
192	            throw e;
193	        }
194	        return toResponse(saved);
195	    }
196	
197	    // ============================= 例行巡检开始 =============================
198	
199	    /**
200	     * 开始：取跑道行锁后重新确认日历版本（按最新占用窗重算，冲突拒绝）且无进行中紧急关闭。
201	     * expectedVersion 乐观锁；requestId 幂等。事务以幂等执行器为界（不在本方法另开事务）。
202	     */
203	    public PlanResponse startPlan(long planId, PlanStartRequest request) {
204	        String fingerprint = StructuredFingerprint.sha256(SCOPE_START,
205	                request.requestId(), String.valueOf(planId), String.valueOf(request.expectedVersion()),
206	                request.startedAt().toString());
207	        try {
208	            return idempotencyExecutor.execute(SCOPE_START, request.requestId(), fingerprint,
209	                    () -> doStartPlan(planId, request), PlanResponse.class);
210	        } catch (DuplicateKeyException e) {
211	            PlanResponse replayed = idempotencyExecutor.tryReplay(SCOPE_START, request.requestId(),
212	                    fingerprint, PlanResponse.class);
213	            if (replayed != null) {
214	                return replayed;
215	            }
216	            throw e;
217	        }
218	    }
219	
220	    private PlanResponse doStartPlan(long planId, PlanStartRequest request) {
221	        // 先读计划拿到跑道，再取该跑道行锁，随后行锁重读计划，确保与紧急接报串行化。
222	        String runwayId = planRepository.findById(planId)
223	                .orElseThrow(() -> ApiException.notFound("ROUTINE_PLAN_NOT_FOUND", "例行计划不存在: " + planId))
224	                .runwayId();
225	        runwayLockRepository.lockRunway(runwayId);
226	        RoutinePlan plan = planRepository.findByIdForUpdate(planId)
227	                .orElseThrow(() -> ApiException.notFound("ROUTINE_PLAN_NOT_FOUND", "例行计划不存在: " + planId));
228	        if (plan.version() != request.expectedVersion()) {
229	            throw ApiException.conflict("PLAN_VERSION_CONFLICT",
230	                    "计划版本已变更，当前=" + plan.version() + "，expectedVersion=" + request.expectedVersion());
231	        }
232	        if (plan.status() != RoutinePlanStatus.APPROVED && plan.status() != RoutinePlanStatus.NEEDS_REVIEW) {
233	            throw ApiException.unprocessable("PLAN_NOT_STARTABLE",
234	                    "仅获准或待重审（未开始）计划可开始，当前状态=" + plan.status());
235	        }
236	        if (request.startedAt().isBefore(plan.windowStart()) || !request.startedAt().isBefore(plan.windowEnd())) {
237	            throw ApiException.unprocessable("START_NOT_WITHIN_WINDOW", "开始时刻须落在巡检半开窗口内");
238	        }
239	        Instant actualInspectionEnd = request.startedAt().plus(plan.durationMinutes(), ChronoUnit.MINUTES);
240	        if (actualInspectionEnd.isAfter(plan.windowEnd())) {
241	            throw ApiException.unprocessable("INSPECTION_NOT_WITHIN_WINDOW",
242	                    "按实际开始时刻推算，巡检时长超出窗口");
243	        }
244	        if (eventRepository.existsActiveByRunway(plan.runwayId())) {
245	            throw ApiException.unprocessable("EMERGENCY_CLOSURE_ACTIVE",
246	                    "跑道存在进行中紧急关闭事件，例行巡检不得开始");
247	        }
248	        int latest = latestCalendarVersion();
249	        List<FlightOccupancyWindow> windows =
250	                occupancyRepository.findByVersionAndRunway(latest, plan.runwayId());
251	        ConflictEvidence evidence = buildEvidence(plan.runwayId(), latest, plan.windowStart(), plan.windowEnd(),
252	                request.startedAt(), actualInspectionEnd, windows);
253	        if (evidence.conflict()) {
254	            throw ApiException.unprocessable("CALENDAR_REVIEW_CONFLICT",
255	                    "依据最新日历版本(" + latest + ")重审存在占用冲突，不得开始", writeEvidence(evidence));
256	        }
257	        Instant now = clock.instant();
258	        RoutinePlan started = new RoutinePlan(plan.id(), plan.runwayId(), plan.windowStart(), plan.windowEnd(),
259	                plan.durationMinutes(), latest, plan.version() + 1, RoutinePlanStatus.STARTED,
260	                writeEvidence(evidence), plan.slotFlag(), null, request.startedAt(), null, null,
261	                plan.requestId(), plan.createdAt(), now);
262	        planRepository.update(started);
263	        return toResponse(planRepository.findById(planId).orElseThrow());
264	    }
265	
266	    // ============================= 检查项回报 =============================
267	
268	    /**
269	     * 检查项回报：进行中（STARTED）正常保存并使聚合版本+1；
270	     * 计划被紧急取消/中止或已关闭后仅登记迟到（late=1），不改变状态、不开放跑道。requestId 幂等。
271	     * 事务以幂等执行器为界。
272	     */
273	    public PlanCheckReportResponse reportChecks(long planId, PlanCheckReportRequest request) {
274	        if (request.items().isEmpty()) {
275	            throw ApiException.badRequest("EMPTY_CHECK_ITEMS", "检查项集合不能为空");
276	        }
277	        List<List<String>> itemFields = request.items().stream()
278	                .map(i -> List.of(i.itemCode(), i.itemText(), String.valueOf(i.passed()),
279	                        i.completedAt().toString()))
280	                .toList();
281	        String fingerprint = StructuredFingerprint.sha256WithCollection(SCOPE_CHECK,
282	                List.of(request.requestId(), String.valueOf(planId), String.valueOf(request.expectedVersion()),
283	                        request.reportedAt().toString()),
284	                itemFields);
285	        try {
286	            return idempotencyExecutor.execute(SCOPE_CHECK, request.requestId(), fingerprint,
287	                    () -> doReportChecks(planId, request), PlanCheckReportResponse.class);
288	        } catch (DuplicateKeyException e) {
289	            PlanCheckReportResponse replayed = idempotencyExecutor.tryReplay(SCOPE_CHECK,
290	                    request.requestId(), fingerprint, PlanCheckReportResponse.class);
291	            if (replayed != null) {
292	                return replayed;
293	            }
294	            throw e;
295	        }
296	    }
297	
298	    private PlanCheckReportResponse doReportChecks(long planId, PlanCheckReportRequest request) {
299	        RoutinePlan plan = planRepository.findByIdForUpdate(planId)
300	                .orElseThrow(() -> ApiException.notFound("ROUTINE_PLAN_NOT_FOUND", "例行计划不存在: " + planId));
301	        if (plan.version() != request.expectedVersion()) {
302	            throw ApiException.conflict("PLAN_VERSION_CONFLICT",
303	                    "计划版本已变更，当前=" + plan.version() + "，expectedVersion=" + request.expectedVersion());
304	        }
305	        boolean late = switch (plan.status()) {
306	            case STARTED -> false;
307	            case ABORTED, CANCELLED, COMPLETED -> true;
308	            default -> throw ApiException.unprocessable("PLAN_NOT_STARTED",
309	                    "巡检尚未开始，不受理检查项回报，当前状态=" + plan.status());
310	        };
311	        Instant now = clock.instant();
312	        List<PlanCheckReportResponse.SavedCheckItem> saved = new ArrayList<>();
313	        for (CheckItemInput item : request.items()) {
314	            RoutineCheckItem row = checkItemRepository.insert(new RoutineCheckItem(0L, planId, item.itemCode(),
315	                    item.itemText(), item.passed(), item.completedAt(), late, request.requestId(), now));
316	            saved.add(new PlanCheckReportResponse.SavedCheckItem(row.id(), row.itemCode(), row.itemText(),
317	                    row.passed(), row.late()));
318	        }
319	        RoutinePlan current = plan;
320	        if (!late) {
321	            // 进行中回报：追加检查项属聚合变更，版本+1，状态仍为 STARTED。
322	            RoutinePlan changed = new RoutinePlan(plan.id(), plan.runwayId(), plan.windowStart(), plan.windowEnd(),
323	                    plan.durationMinutes(), plan.calendarVersion(), plan.version() + 1, plan.status(),
324	                    plan.evidence(), plan.slotFlag(), null, plan.startedAt(), plan.completedAt(),
325	                    plan.preemptedAt(), plan.requestId(), plan.createdAt(), now);
326	            planRepository.update(changed);
327	            current = planRepository.findById(planId).orElseThrow();
328	        }
329	        return new PlanCheckReportResponse(planId, current.status().name(), current.version(), late, saved);
330	    }
331	
332	    // ============================= 完成回报 =============================
333	
334	    /**
335	     * 完成回报：进行中正常完成只关闭计划（COMPLETED，释放获准位），不触发恢复开放/通告；
336	     * 被紧急取消/中止或已完成后的回报仅登记迟到，不开放跑道。requestId 幂等。事务以幂等执行器为界。
337	     */
338	    public PlanCompletionResponse completePlan(long planId, PlanCompletionRequest request) {
339	        String fingerprint = StructuredFingerprint.sha256(SCOPE_COMPLETION,
340	                request.requestId(), String.valueOf(planId), String.valueOf(request.expectedVersion()),
341	                request.completedAt().toString());
342	        try {
343	            return idempotencyExecutor.execute(SCOPE_COMPLETION, request.requestId(), fingerprint,
344	                    () -> doCompletePlan(planId, request), PlanCompletionResponse.class);
345	        } catch (DuplicateKeyException e) {
346	            PlanCompletionResponse replayed = idempotencyExecutor.tryReplay(SCOPE_COMPLETION,
347	                    request.requestId(), fingerprint, PlanCompletionResponse.class);
348	            if (replayed != null) {
349	                return replayed;
350	            }
351	            throw e;
352	        }
353	    }
354	
355	    private PlanCompletionResponse doCompletePlan(long planId, PlanCompletionRequest request) {
356	        RoutinePlan plan = planRepository.findByIdForUpdate(planId)
357	                .orElseThrow(() -> ApiException.notFound("ROUTINE_PLAN_NOT_FOUND", "例行计划不存在: " + planId));
358	        if (plan.version() != request.expectedVersion()) {
359	            throw ApiException.conflict("PLAN_VERSION_CONFLICT",
360	                    "计划版本已变更，当前=" + plan.version() + "，expectedVersion=" + request.expectedVersion());
361	        }
362	        Instant now = clock.instant();
363	        if (plan.status() == RoutinePlanStatus.STARTED) {
364	            completionRepository.insert(new RoutineCompletionReport(0L, planId, request.completedAt(), false,
365	                    request.requestId(), now));
366	            RoutinePlan completed = new RoutinePlan(plan.id(), plan.runwayId(), plan.windowStart(),
367	                    plan.windowEnd(), plan.durationMinutes(), plan.calendarVersion(), plan.version() + 1,
368	                    RoutinePlanStatus.COMPLETED, plan.evidence(), plan.slotFlag(), plan.emergencyEventId(),
369	                    plan.startedAt(), request.completedAt(), plan.preemptedAt(), plan.requestId(),
370	                    plan.createdAt(), now);
371	            planRepository.update(completed);
372	            RoutinePlan saved = planRepository.findById(planId).orElseThrow();
373	            return new PlanCompletionResponse(planId, saved.status().name(), saved.version(), false,
374	                    request.completedAt());
375	        }
376	        if (plan.status() == RoutinePlanStatus.ABORTED || plan.status() == RoutinePlanStatus.CANCELLED
377	                || plan.status() == RoutinePlanStatus.COMPLETED) {
378	            // 被抢占后（或已关闭后）的迟到完成回报：只登记，不复活、不开放跑道，计划聚合不变更。
379	            completionRepository.insert(new RoutineCompletionReport(0L, planId, request.completedAt(), true,
380	                    request.requestId(), now));
381	            return new PlanCompletionResponse(planId, plan.status().name(), plan.version(), true,
382	                    request.completedAt());
383	        }
384	        throw ApiException.unprocessable("PLAN_NOT_STARTED",
385	                "巡检尚未开始，不受理完成回报，当前状态=" + plan.status());
386	    }
387	
388	    // ============================= 查询 =============================
389	
390	    @Transactional(readOnly = true)
391	    public PlanResponse getPlan(long planId) {
392	        return toResponse(planRepository.findById(planId)
393	                .orElseThrow(() -> ApiException.notFound("ROUTINE_PLAN_NOT_FOUND", "例行计划不存在: " + planId)));
394	    }
395	
396	    @Transactional(readOnly = true)
397	    public List<PlanResponse> listPlans(String runwayId) {
398	        return planRepository.findByRunway(runwayId).stream().map(this::toResponse).toList();
399	    }
400	
401	    /**
402	     * 日历影响查询：返回该版本占用窗，以及冻结在该版本、因变更待重审的未开始计划。
403	     */
404	    @Transactional(readOnly = true)
405	    public CalendarImpactResponse getCalendarImpact(int version) {
406	        FlightCalendarVersion calendar = calendarRepository.findByVersion(version)
407	                .orElseThrow(() -> ApiException.notFound("CALENDAR_VERSION_NOT_FOUND",
408	                        "航班日历版本不存在: " + version));
409	        List<OccupancyView> occupancies = occupancyRepository.findByVersion(version).stream()
410	                .map(w -> new OccupancyView(w.windowStart(), w.windowEnd()))
411	                .toList();
412	        // 待重审且冻结版本早于查询版本：即因截至该版本的日历变更而受影响的未开始计划。
413	        List<PlanResponse> impacted = planRepository.findNeedsReview().stream()
414	                .filter(p -> p.calendarVersion() < version)
415	                .map(this::toResponse)
416	                .toList();
417	        return new CalendarImpactResponse(version, calendar.publishedAt(), occupancies, impacted);
418	    }
419	
420	    // ============================= 内部工具 =============================
421	
422	    private int latestCalendarVersion() {
423	        return calendarRepository.findMaxVersion()
424	                .orElseThrow(() -> ApiException.badRequest("CALENDAR_NOT_INITIALIZED", "航班日历尚未初始化"));
425	    }
426	
427	    /**
428	     * 构造结构化冲突证据：实际巡检区间为 [inspectionStart, inspectionEnd)，
429	     * 与占用窗 [s,e) 正长度相交（max(start) &lt; min(end)）即冲突；端点相接（相等）不相交，合法。
430	     */
431	    private ConflictEvidence buildEvidence(String runwayId, int calendarVersion, Instant windowStart,
432	                                           Instant windowEnd, Instant inspectionStart, Instant inspectionEnd,
433	                                           List<FlightOccupancyWindow> windows) {
434	        List<OccupancyView> considered = windows.stream()
435	                .map(w -> new OccupancyView(w.windowStart(), w.windowEnd()))
436	                .toList();
437	        List<OccupancyView> conflicting = windows.stream()
438	                .filter(w -> inspectionStart.isBefore(w.windowEnd()) && w.windowStart().isBefore(inspectionEnd))
439	                .map(w -> new OccupancyView(w.windowStart(), w.windowEnd()))
440	                .toList();
441	        return new ConflictEvidence(runwayId, calendarVersion, windowStart, windowEnd, inspectionStart,
442	                inspectionEnd, !conflicting.isEmpty(), considered, conflicting);
443	    }
444	
445	    private String writeEvidence(ConflictEvidence evidence) {
446	        try {
447	            return objectMapper.writeValueAsString(evidence);
448	        } catch (JsonProcessingException e) {
449	            throw new IllegalStateException("冲突证据序列化失败", e);
450	        }
451	    }
452	
453	    private PlanResponse toResponse(RoutinePlan plan) {
454	        Instant inspectionEnd = plan.startedAt() != null
455	                ? plan.startedAt().plus(plan.durationMinutes(), ChronoUnit.MINUTES)
456	                : plan.windowStart().plus(plan.durationMinutes(), ChronoUnit.MINUTES);
457	        return new PlanResponse(plan.id(), plan.runwayId(), plan.windowStart(), plan.windowEnd(),
458	                plan.durationMinutes(), plan.calendarVersion(), plan.version(), plan.status().name(),
459	                inspectionEnd, plan.emergencyEventId(), plan.startedAt(), plan.completedAt(),
460	                plan.preemptedAt(), plan.evidence());
461	    }
462	
463	    private boolean isSlotConflict(DuplicateKeyException e) {
464	        String message = String.valueOf(e.getMessage()).toLowerCase(Locale.ROOT);
465	        return message.contains("uk_routine_plan_slot");
466	    }
467	
468	    private boolean isVersionConflict(DuplicateKeyException e) {
469	        String message = String.valueOf(e.getMessage()).toLowerCase(Locale.ROOT);
470	        return message.contains("uk_flight_calendar_version");
471	    }
472	}
