1	package com.example.starter.runway;
2	
3	import com.fasterxml.jackson.databind.ObjectMapper;
4	import org.springframework.stereotype.Component;
5	import org.springframework.transaction.annotation.Transactional;
6	
7	import java.util.function.Supplier;
8	
9	/**
10	 * 幂等执行器：在同一事务内完成“查重→执行业务→登记幂等记录”。
11	 * 指纹覆盖 requestId 与全部业务字段；同键同参返回首次结果，同键异参返回 409。
12	 */
13	@Component
14	public class IdempotencyExecutor {
15	
16	    private final IdempotencyRepository repository;
17	    private final ObjectMapper objectMapper;
18	
19	    public IdempotencyExecutor(IdempotencyRepository repository, ObjectMapper objectMapper) {
20	        this.repository = repository;
21	        this.objectMapper = objectMapper;
22	    }
23	
24	    /**
25	     * 幂等执行：已存在同键记录时按指纹决定重放或 409，否则执行业务并登记。
26	     */
27	    @Transactional
28	    public <T> T execute(String scope, String requestId, String fingerprint, Supplier<T> action, Class<T> type) {
29	        var existing = repository.find(scope, requestId);
30	        if (existing.isPresent()) {
31	            IdempotencyRepository.IdemRow row = existing.get();
32	            if (!row.fingerprint().equals(fingerprint)) {
33	                throw ApiException.conflict("IDEMPOTENCY_CONFLICT", "相同 requestId 的业务参数不一致");
34	            }
35	            return read(row.responseBody(), type);
36	        }
37	        T result = action.get();
38	        repository.insert(scope, requestId, fingerprint, write(result));
39	        return result;
40	    }
41	
42	    /**
43	     * 并发冲突后的重放尝试（原事务已回滚，此处新连接只读）：
44	     * 无幂等记录返回 null；有记录且指纹一致返回首次结果；指纹不一致抛 409。
45	     */
46	    public <T> T tryReplay(String scope, String requestId, String fingerprint, Class<T> type) {
47	        var existing = repository.find(scope, requestId);
48	        if (existing.isEmpty()) {
49	            return null;
50	        }
51	        IdempotencyRepository.IdemRow row = existing.get();
52	        if (!row.fingerprint().equals(fingerprint)) {
53	            throw ApiException.conflict("IDEMPOTENCY_CONFLICT", "相同 requestId 的业务参数不一致");
54	        }
55	        return read(row.responseBody(), type);
56	    }
57	
58	    private <T> T read(String body, Class<T> type) {
59	        try {
60	            return objectMapper.readValue(body, type);
61	        } catch (Exception e) {
62	            throw new IllegalStateException("幂等响应反序列化失败", e);
63	        }
64	    }
65	
66	    private String write(Object value) {
67	        try {
68	            return objectMapper.writeValueAsString(value);
69	        } catch (Exception e) {
70	            throw new IllegalStateException("幂等响应序列化失败", e);
71	        }
72	    }
