18	 * 例行巡检计划数据访问：routine_plan 表。
19	 */
20	@Repository
21	public class RoutinePlanRepository {
22	
23	    private static final RowMapper<RoutinePlan> MAPPER = (rs, rowNum) -> new RoutinePlan(
24	            rs.getLong("id"),
25	            rs.getString("runway_id"),
26	            rs.getTimestamp("window_start").toInstant(),
27	            rs.getTimestamp("window_end").toInstant(),
28	            rs.getInt("duration_minutes"),
29	            rs.getInt("calendar_version"),
30	            rs.getInt("version"),
31	            RoutinePlanStatus.valueOf(rs.getString("status")),
32	            rs.getString("evidence"),
33	            (Integer) rs.getObject("slot_flag"),
34	            (Long) rs.getObject("emergency_event_id"),
35	            rs.getTimestamp("started_at") == null ? null : rs.getTimestamp("started_at").toInstant(),
36	            rs.getTimestamp("completed_at") == null ? null : rs.getTimestamp("completed_at").toInstant(),
37	            rs.getTimestamp("preempted_at") == null ? null : rs.getTimestamp("preempted_at").toInstant(),
38	            rs.getString("request_id"),
39	            rs.getTimestamp("created_at").toInstant(),
40	            rs.getTimestamp("updated_at").toInstant());
41	
42	    private final JdbcTemplate jdbc;
43	
44	    public RoutinePlanRepository(JdbcTemplate jdbc) {
45	        this.jdbc = jdbc;
46	    }
47	
48	    /** 插入计划；slotFlag=1 时占用“同跑道同窗唯一获准”唯一索引。初始聚合版本为1。 */
49	    public RoutinePlan insert(RoutinePlan plan) {
50	        KeyHolder keyHolder = new GeneratedKeyHolder();
51	        jdbc.update(connection -> {
52	            PreparedStatement ps = connection.prepareStatement(
53	                    "INSERT INTO routine_plan (runway_id, window_start, window_end, duration_minutes,"
54	                            + " calendar_version, version, status, evidence, slot_flag, emergency_event_id,"
55	                            + " started_at, completed_at, preempted_at, request_id, created_at, updated_at)"
56	                            + " VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
57	                    Statement.RETURN_GENERATED_KEYS);
58	            ps.setString(1, plan.runwayId());
59	            ps.setTimestamp(2, Timestamp.from(plan.windowStart()));
60	            ps.setTimestamp(3, Timestamp.from(plan.windowEnd()));
61	            ps.setInt(4, plan.durationMinutes());
62	            ps.setInt(5, plan.calendarVersion());
63	            ps.setInt(6, plan.version() <= 0 ? 1 : plan.version());
64	            ps.setString(7, plan.status().name());
65	            ps.setString(8, plan.evidence());
66	            if (plan.slotFlag() == null) {
67	                ps.setNull(9, Types.TINYINT);
68	            } else {
69	                ps.setInt(9, plan.slotFlag());
70	            }
71	            if (plan.emergencyEventId() == null) {
72	                ps.setNull(10, Types.BIGINT);
73	            } else {
74	                ps.setLong(10, plan.emergencyEventId());
75	            }
76	            ps.setTimestamp(11, plan.startedAt() == null ? null : Timestamp.from(plan.startedAt()));
77	            ps.setTimestamp(12, plan.completedAt() == null ? null : Timestamp.from(plan.completedAt()));
78	            ps.setTimestamp(13, plan.preemptedAt() == null ? null : Timestamp.from(plan.preemptedAt()));
79	            ps.setString(14, plan.requestId());
80	            ps.setTimestamp(15, Timestamp.from(plan.createdAt()));
81	            ps.setTimestamp(16, Timestamp.from(plan.updatedAt()));
82	            return ps;
83	        }, keyHolder);
84	        long id = Optional.ofNullable(keyHolder.getKey()).orElseThrow().longValue();
85	        return findById(id).orElseThrow();
86	    }
87	
88	    public Optional<RoutinePlan> findById(long id) {
89	        List<RoutinePlan> rows = jdbc.query("SELECT * FROM routine_plan WHERE id = ?", MAPPER, id);
90	        return rows.stream().findFirst();
91	    }
92	
93	    /** 按跑道列出全部计划（含终态），按时间与主键排序。 */
94	    public List<RoutinePlan> findByRunway(String runwayId) {
95	        return jdbc.query("SELECT * FROM routine_plan WHERE runway_id = ? ORDER BY window_start, id",
96	                MAPPER, runwayId);
97	    }
98	
99	    /** 行级锁定取计划，供开始/完成/抢占等状态流转串行化。 */
100	    public Optional<RoutinePlan> findByIdForUpdate(long id) {
101	        List<RoutinePlan> rows = jdbc.query("SELECT * FROM routine_plan WHERE id = ? FOR UPDATE", MAPPER, id);
102	        return rows.stream().findFirst();
103	    }
104	
105	    /** 取同跑道同窗、且仍占用唯一获准位（slot_flag=1）的计划。 */
106	    public List<RoutinePlan> findSlotHolders(String runwayId, Instant windowStart, Instant windowEnd) {
107	        return jdbc.query(
