71	                new ReopenRequest("reopen-1", T0.plus(Duration.ofMinutes(10))));
72	        assertEquals(EventStatus.REOPENED.name(), reopened.status());
73	        assertTrue(reopened.notamNo().startsWith("NTM-R-"));
