217	    @Test
218	    void concurrentReportsOnlyOneActiveEventAccepted() throws Exception {
219	        int threads = 8;
220	        ExecutorService pool = Executors.newFixedThreadPool(threads);
221	        CountDownLatch ready = new CountDownLatch(threads);
222	        CountDownLatch start = new CountDownLatch(1);
223	        AtomicInteger success = new AtomicInteger();
224	        AtomicInteger conflict = new AtomicInteger();
225	        List<Future<?>> futures = new java.util.ArrayList<>();
226	
227	        for (int i = 0; i < threads; i++) {
228	            final int idx = i;
229	            futures.add(pool.submit(() -> {
230	                ready.countDown();
231	                start.await();
232	                try {
233	                    service.report(new ReportRequest("cc-req-" + idx, "RW08", EventType.PAVEMENT_DAMAGE, T0));
234	                    success.incrementAndGet();
235	                } catch (ApiException e) {
236	                    if ("RUNWAY_ACTIVE_EVENT_EXISTS".equals(e.getCode())) {
237	                        conflict.incrementAndGet();
238	                    } else {
239	                        throw e;
240	                    }
241	                }
242	                return null;
