1	package com.example.starter.runway;
2	
3	import org.springframework.jdbc.core.JdbcTemplate;
4	import org.springframework.jdbc.core.RowMapper;
5	import org.springframework.jdbc.support.GeneratedKeyHolder;
6	import org.springframework.jdbc.support.KeyHolder;
7	import org.springframework.stereotype.Repository;
8	
9	import java.sql.PreparedStatement;
10	import java.sql.Statement;
11	import java.sql.Timestamp;
12	import java.util.List;
13	import java.util.Objects;
14	import java.util.Optional;
15	
16	/**
17	 * 跑道事件数据访问：runway_event 表。
18	 */
19	@Repository
20	public class RunwayEventRepository {
21	
22	    private static final RowMapper<RunwayEvent> MAPPER = (rs, rowNum) -> new RunwayEvent(
23	            rs.getLong("id"),
24	            rs.getString("runway_id"),
25	            EventType.valueOf(rs.getString("event_type")),
26	            EventStatus.valueOf(rs.getString("status")),
27	            rs.getTimestamp("reported_at").toInstant(),
28	            rs.getTimestamp("closed_at").toInstant(),
29	            rs.getTimestamp("inspection_deadline").toInstant(),
30	            rs.getBoolean("escalated"),
31	            rs.getString("assessment_type") == null ? null : AssessmentType.valueOf(rs.getString("assessment_type")),
32	            rs.getString("request_id"),
33	            rs.getTimestamp("created_at").toInstant(),
34	            rs.getTimestamp("updated_at").toInstant());
35	
36	    private final JdbcTemplate jdbc;
37	
38	    public RunwayEventRepository(JdbcTemplate jdbc) {
39	        this.jdbc = jdbc;
40	    }
41	
42	    /**
43	     * 插入事件；activeFlag 为 1 时占用“跑道唯一进行中事件”唯一索引。
44	     */
45	    public RunwayEvent insert(RunwayEvent event, Integer activeFlag) {
46	        KeyHolder keyHolder = new GeneratedKeyHolder();
47	        jdbc.update(connection -> {
48	            PreparedStatement ps = connection.prepareStatement(
49	                    "INSERT INTO runway_event (runway_id, event_type, status, reported_at, closed_at,"
50	                            + " inspection_deadline, escalated, assessment_type, active_flag, request_id,"
51	                            + " created_at, updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",
52	                    Statement.RETURN_GENERATED_KEYS);
53	            ps.setString(1, event.runwayId());
54	            ps.setString(2, event.eventType().name());
55	            ps.setString(3, event.status().name());
56	            ps.setTimestamp(4, Timestamp.from(event.reportedAt()));
57	            ps.setTimestamp(5, Timestamp.from(event.closedAt()));
58	            ps.setTimestamp(6, Timestamp.from(event.inspectionDeadline()));
59	            ps.setBoolean(7, event.escalated());
60	            ps.setString(8, event.assessmentType() == null ? null : event.assessmentType().name());
61	            if (activeFlag == null) {
62	                ps.setNull(9, java.sql.Types.TINYINT);
63	            } else {
64	                ps.setInt(9, activeFlag);
65	            }
66	            ps.setString(10, event.requestId());
67	            ps.setTimestamp(11, Timestamp.from(event.createdAt()));
68	            ps.setTimestamp(12, Timestamp.from(event.updatedAt()));
69	            return ps;
70	        }, keyHolder);
71	        long id = Objects.requireNonNull(keyHolder.getKey()).longValue();
72	        return findById(id).orElseThrow();
73	    }
74	
75	    public Optional<RunwayEvent> findById(long id) {
76	        List<RunwayEvent> rows = jdbc.query("SELECT * FROM runway_event WHERE id = ?", MAPPER, id);
77	        return rows.stream().findFirst();
78	    }
79	
80	    /**
81	     * 更新状态；clearActiveFlag 为真时释放“进行中”唯一占位（恢复/归档）。
82	     */
83	    public void updateStatus(long id, EventStatus status, boolean escalated, AssessmentType assessmentType,
84	                             boolean clearActiveFlag, java.time.Instant updatedAt) {
85	        jdbc.update("UPDATE runway_event SET status = ?, escalated = ?, assessment_type = ?,"
86	                        + " active_flag = CASE WHEN ? THEN NULL ELSE active_flag END, updated_at = ? WHERE id = ?",
87	                status.name(), escalated,
88	                assessmentType == null ? null : assessmentType.name(),
89	                clearActiveFlag, Timestamp.from(updatedAt), id);
90	    }
91	
92	    public List<RunwayEvent> findAll() {
93	        return jdbc.query("SELECT * FROM runway_event ORDER BY id", MAPPER);
94	    }
95	
96	    /** 行级锁定取某跑道进行中紧急关闭事件（active_flag=1），供例行开始校验与紧急抢占串行化。 */
