package com.example.starter.runway.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Positive;

/**
 * 受控跑道登记请求：登记正整数米长度。requestId 为幂等标识。
 *
 * @param requestId    幂等请求标识（指纹覆盖该字段与全部业务字段）
 * @param runwayId     跑道编号（合成数据）
 * @param lengthMeters 跑道长度（单位：米，正整数）
 */
public record RunwayRegisterRequest(
        @NotBlank String requestId,
        @NotBlank String runwayId,
        @Positive int lengthMeters) {
}

package com.example.starter.runway.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Positive;

/**
 * 受控跑道长度变更请求：存在活动施工后不许缩改。expectedVersion 乐观锁。
 *
 * @param requestId       幂等请求标识
 * @param expectedVersion 期望的跑道聚合版本，不符返回409
 * @param lengthMeters    新跑道长度（单位：米，正整数）
 */
public record RunwayResizeRequest(
        @NotBlank String requestId,
        int expectedVersion,
        @Positive int lengthMeters) {
}

package com.example.starter.runway.dto;

import java.time.Instant;

/**
 * 受控跑道响应。
 *
 * @param runwayId     跑道编号
 * @param lengthMeters 跑道长度（单位：米）
 * @param version      聚合乐观锁版本
 * @param createdAt    登记时间（UTC）
 * @param updatedAt    最近变更时间（UTC）
 */
public record ControlledRunwayResponse(
        String runwayId,
        int lengthMeters,
        int version,
        Instant createdAt,
        Instant updatedAt) {
}

package com.example.starter.runway.dto;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.PositiveOrZero;

/**
 * 施工段输入：半开整数米区间 [startMeters, endMeters)。
 *
 * @param segmentNo   段号（1至10，单内唯一）
 * @param startMeters 段起点（单位：米，含），0<=start<end<=跑道长度
 * @param endMeters   段终点（单位：米，不含）
 */
public record ConstructionSegmentInput(
        @Min(1) @Max(10) int segmentNo,
        @PositiveOrZero int startMeters,
        @Min(1) int endMeters) {
}

package com.example.starter.runway.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 施工单登记请求：引用受控跑道及1至10个不同段号。requestId 为幂等标识。
 *
 * @param requestId 幂等请求标识（指纹覆盖该字段与全部业务字段）
 * @param runwayId  受控跑道编号
 * @param segments  施工段集合：1至10个不同段号，单内区间不得重叠（端点相接允许）
 */
public record ConstructionOrderCreateRequest(
        @NotBlank String requestId,
        @NotBlank String runwayId,
        @NotEmpty @Size(max = 10) List<@Valid ConstructionSegmentInput> segments) {
}

package com.example.starter.runway.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 施工单修改请求：仅未生效单据可整体替换施工段；已生效不得缩段。expectedVersion 乐观锁。
 *
 * @param requestId       幂等请求标识
 * @param expectedVersion 期望的施工单聚合版本，不符返回409
 * @param segments        新施工段集合：1至10个不同段号，单内区间不得重叠（端点相接允许）
 */
public record ConstructionOrderModifyRequest(
        @NotBlank String requestId,
        int expectedVersion,
        @NotEmpty @Size(max = 10) List<@Valid ConstructionSegmentInput> segments) {
}

package com.example.starter.runway.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.time.Instant;

/**
 * 施工单生效请求：冻结区间并闭锁整跑道。expectedVersion 乐观锁。
 *
 * @param requestId       幂等请求标识
 * @param expectedVersion 期望的施工单聚合版本，不符返回409
 * @param activatedAt     生效时刻（UTC，精确时刻由请求给出）
 */
public record ConstructionActivateRequest(
        @NotBlank String requestId,
        int expectedVersion,
        @NotNull Instant activatedAt) {
}

package com.example.starter.runway.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 施工单撤回请求：仅未生效单据可撤回；已生效不得删除或缩段。expectedVersion 乐观锁。
 *
 * @param requestId       幂等请求标识
 * @param expectedVersion 期望的施工单聚合版本，不符返回409
 */
public record ConstructionWithdrawRequest(
        @NotBlank String requestId,
        int expectedVersion) {
}

package com.example.starter.runway.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.time.Instant;

/**
 * 验收清场凭据提交请求（合成）：每段须两个不同验收人各提交一条。requestId 为幂等标识。
 *
 * @param requestId   幂等请求标识（指纹覆盖该字段与全部业务字段）
 * @param inspectorId 验收人标识（合成）；同段同一验收人仅计一次
 * @param credential  合成清场凭据文本
 * @param submittedAt 凭据提交时刻（UTC，精确时刻由请求给出）
 */
public record AcceptanceRequest(
        @NotBlank String requestId,
        @NotBlank String inspectorId,
        @NotBlank String credential,
        @NotNull Instant submittedAt) {
}

package com.example.starter.runway.dto;

import java.time.Instant;

/**
 * 施工段视图。
 *
 * @param segmentNo       段号
 * @param startMeters     段起点（单位：米，含）
 * @param endMeters       段终点（单位：米，不含）
 * @param status          段状态：LOCKED闭锁中/COMPLETED验收完成
 * @param completedAt     段验收完成时刻（UTC），未完成为 null
 * @param acceptanceCount 已登记验收凭据数（不含迟到登记）
 */
public record SegmentView(
        int segmentNo,
        int startMeters,
        int endMeters,
        String status,
        Instant completedAt,
        int acceptanceCount) {
}

package com.example.starter.runway.dto;

/**
 * 米制半开区间视图：[startMeters, endMeters)。
 *
 * @param startMeters 区间起点（单位：米，含）
 * @param endMeters   区间终点（单位：米，不含）
 * @param lengthMeters 区间长度（单位：米，endMeters-startMeters）
 */
public record IntervalView(
        int startMeters,
        int endMeters,
        int lengthMeters) {
}

package com.example.starter.runway.dto;

import java.util.List;

/**
 * 可用区域查询响应：可用区间为所有活动施工区间并集的补集，重叠不重复计长度。
 *
 * @param runwayId               跑道编号
 * @param lengthMeters           跑道长度（单位：米）
 * @param unavailable            闭锁区间并集（已合并重叠，按起点排序）
 * @param available              可用区间列表（补集，按起点排序）；空可用返回空列表
 * @param unavailableTotalMeters 闭锁总长度（单位：米，并集口径，重叠不重复计）
 * @param availableTotalMeters   可用总长度（单位：米）
 */
public record AvailableAreasResponse(
        String runwayId,
        int lengthMeters,
        List<IntervalView> unavailable,
        List<IntervalView> available,
        int unavailableTotalMeters,
        int availableTotalMeters) {
}

